<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Diário Official - Abril 1910</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;1,400&family=EB+Garamond:ital,wght@0,400;0,700;1,400&display=swap');

  body {
    background-color: #f5f0e8;
    color: #1a1a1a;
    font-family: 'EB Garamond', 'Georgia', serif;
    font-size: 14px;
    line-height: 1.5;
    margin: 0;
    padding: 20px;
  }

  .page {
    max-width: 900px;
    margin: 0 auto;
    background-color: #f5f0e8;
    padding: 20px 30px;
  }

  .header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 2px solid #1a1a1a;
    padding-bottom: 5px;
    margin-bottom: 15px;
    font-family: 'Playfair Display', serif;
    font-weight: 700;
    font-size: 16px;
  }

  .header .page-num {
    font-size: 16px;
  }

  .header .title {
    font-size: 20px;
    letter-spacing: 3px;
    text-transform: uppercase;
  }

  .header .date {
    font-size: 16px;
  }

  .columns {
    display: flex;
    gap: 30px;
  }

  .column {
    flex: 1;
    text-align: justify;
    hyphens: auto;
  }

  .column p {
    margin-bottom: 8px;
    text-indent: 2em;
  }

  .column p.no-indent {
    text-indent: 0;
  }

  .clause-title {
    text-align: center;
    font-family: 'Playfair Display', serif;
    font-weight: 700;
    font-size: 18px;
    margin: 15px 0 10px 0;
    letter-spacing: 2px;
  }

  .letter-item {
    text-indent: 0;
    margin-bottom: 8px;
  }

  .letter-item .letter {
    font-weight: 700;
  }

  .sub-text {
    text-indent: 2em;
    margin-bottom: 8px;
  }

  .separator {
    border: none;
    border-top: 1px solid #1a1a1a;
    margin: 10px 0;
